package com.sunmo.stockplatform.scanner.api;
import com.sunmo.stockplatform.scanner.domain.*;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;
public final class ScannerDtos {private ScannerDtos(){}public record SettingRequest(@NotBlank @Size(max=100)String name,@NotNull ScannerType type,@NotNull @PositiveOrZero BigDecimal minChangeRate,@NotNull @PositiveOrZero BigDecimal minVolumeRatio,@NotNull @PositiveOrZero BigDecimal minFiveMinuteTradingValue,@NotNull @PositiveOrZero BigDecimal minDailyTradingValue,@NotNull @PositiveOrZero BigDecimal minPrice,boolean includeEtf,@Min(1)int cooldownSeconds,boolean active,@PositiveOrZero long version){}public record SettingResponse(Long id,String name,ScannerType type,BigDecimal minChangeRate,BigDecimal minVolumeRatio,BigDecimal minFiveMinuteTradingValue,BigDecimal minDailyTradingValue,BigDecimal minPrice,boolean includeEtf,int cooldownSeconds,boolean active,long version){public static SettingResponse from(ScannerSetting s){return new SettingResponse(s.getId(),s.getName(),s.getType(),s.getMinChangeRate(),s.getMinVolumeRatio(),s.getMinFiveMinuteTradingValue(),s.getMinDailyTradingValue(),s.getMinPrice(),s.isIncludeEtf(),s.getCooldownSeconds(),s.isActive(),s.getVersion());}}public record DetectionResponse(Long id,String eventId,String scannerType,String stockCode,String stockName,String market,Instant detectedAt,BigDecimal detectedPrice,BigDecimal fiveMinuteChangeRate,BigDecimal volumeRatio,long currentFiveMinuteVolume,BigDecimal currentFiveMinuteTradingValue,BigDecimal dailyTradingValue,BigDecimal momentumScore,String settingName,String settingSnapshot){public static DetectionResponse from(ScannerDetection d){return new DetectionResponse(d.getId(),d.getEventId().toString(),d.getType().name(),d.getStock().getStockCode(),d.getStock().getStockName(),d.getStock().getMarket().name(),d.getDetectedAt(),d.getDetectedPrice(),d.getChangeRate(),d.getVolumeRatio(),d.getCurrentVolume(),d.getCurrentValue(),d.getDailyValue(),d.getScore(),d.getSetting().getName(),d.getSettingSnapshot());}}}
